32 = byte_size(Out),
State0 = libsodium_crypto_xof_turboshake128:init(),
State1 = libsodium_crypto_xof_turboshake128:update(State0, <<"hello ">>),
State2 = libsodium_crypto_xof_turboshake128:update(State1, <<"world">>),
{State3, First} = libsodium_crypto_xof_turboshake128:squeeze(State2, 16),
{_State4, Second} = libsodium_crypto_xof_turboshake128:squeeze(State3, 16),
Out = <<First/binary, Second/binary>>.
```
